{"tool":"write","path":"reports/export.py","content":""""Reports CSV exporter."""

_SPECIAL_CHARS = (",", '"', "\r", "\n")


def _escape(field):
    """Apply RFC 4180 minimal quoting and quote doubling to one field."""
    if any(ch in field for ch in _SPECIAL_CHARS):
        return '"' + field.replace('"', '""') + '"'
    return field


def export_csv(rows, columns):
    """Export mappings in column order as RFC 4180 CSV, including the header.

    rows: iterable of mappings (one-shot generators supported).
    columns: ordered iterable of unique string column names.

    Returns a str with a CSV header followed by one record per row, using
    comma delimiters, CRLF record endings, minimal quoting, and quote
    doubling. Missing fields and None become empty strings; other values
    become str(value). Unselected fields are ignored.

    Raises ValueError for duplicate or non-string column names.
    """
    cols = list(columns)  # copy so generators work and inputs are not mutated
    seen = set()
    for name in cols:
        if not isinstance(name, str):
            raise ValueError("column names must be strings, got %r" % (name,))
        if name in seen:
            raise ValueError("duplicate column name: %r" % (name,))
        seen.add(name)

    parts = [",".join(_escape(name) for name in cols) + "\r\n"]
    for row in rows:
        fields = []
        for name in cols:
            value = row.get(name, "")
            if value is None:
                value = ""
            fields.append(_escape(str(value)))
        parts.append(",".join(fields) + "\r\n")
    return "".join(parts)
